export default async function run(ctx) {
  await ctx.page.goto("https://timeline.test/home");

  const guards = [
    ctx.guard.url("timeline\\.test/home"),
    ctx.guard.exists("article", { timeout: 8000 }),
    ctx.guard.noDialog(),
  ];
  if (!(await ctx.guard.all(guards))) {
    return ctx.deopt(
      "Extract each post on the timeline as {text, url} and emit post.detected for every new one, deduplicated on its permalink.",
      { failed: await ctx.guard.failures() },
    );
  }

  const posts = await ctx.page.evalExtract("article", {
    text: { selector: "[data-testid='postText']" },
    url: { selector: "a[href*='/status/']", attr: "href" },
  });
  if (posts.length === 0) {
    return ctx.deopt("The timeline rendered no posts where the compiled run saw some.", { rows: 0 });
  }

  for (const post of posts) {
    await ctx.emit("post.detected", post);
  }
}
